MOTIF_NAME = 'unstoppable_passed_pawn'
MOTIF_DESCRIPTION = 'The side to move has a passed pawn that cannot be caught by the opponent.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Find all pawns for side to move
    stm_pawns = board.pieces(chess.PAWN, stm)
    if not stm_pawns:
        return False

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False

    stm_king_sq = board.king(stm)

    # Get opponent pawns for passed-pawn detection
    opp_pawns = board.pieces(chess.PAWN, opp)

    for pawn_sq in stm_pawns:
        file = chess.square_file(pawn_sq)
        rank = chess.square_rank(pawn_sq)

        # Passed pawn check: no opponent pawns on same or adjacent files ahead
        passed = True
        if stm == chess.WHITE:
            # White pawns go from rank 1 to 7
            for f in (file-1, file, file+1):
                if f < 0 or f > 7:
                    continue
                for r in range(rank+1, 8):
                    sq = chess.square(f, r)
                    if sq in opp_pawns:
                        passed = False
                        break
                if not passed:
                    break
        else:
            # Black pawns go from rank 6 down to 0
            for f in (file-1, file, file+1):
                if f < 0 or f > 7:
                    continue
                for r in range(rank-1, -1, -1):
                    sq = chess.square(f, r)
                    if sq in opp_pawns:
                        passed = False
                        break
                if not passed:
                    break

        if not passed:
            continue

        # Now check if the opponent king can catch this pawn
        promo_rank = 7 if stm == chess.WHITE else 0
        if stm == chess.WHITE:
            dist_to_promo = 7 - rank
        else:
            dist_to_promo = rank - 0

        # squares the pawn needs to advance through
        pawn_path = []
        if stm == chess.WHITE:
            for r in range(rank, 8):
                pawn_path.append(chess.square(file, r))
        else:
            for r in range(rank, -1, -1):
                pawn_path.append(chess.square(file, r))

        # Minimal king distance to any square on the pawn's path
        min_king_dist = min(chess.square_distance(opp_king_sq, sq) for sq in pawn_path)

        # Can opponent king intercept? Factor in whose turn it is (opp moves right after)
        # If it's stm's turn, pawn has a head start
        # Pawn needs dist_to_promo moves. King needs min_king_dist moves.
        # But king can't move through pieces. Simplified: if king distance > pawn distance + 1, unstoppable
        if min_king_dist > dist_to_promo + 1:
            return True

        # Check if own king can block the opponent king from getting to the pawn
        if stm_king_sq is not None:
            # own king is close enough to shield
            if chess.square_distance(stm_king_sq, pawn_sq) <= 3 and chess.square_distance(stm_king_sq, opp_king_sq) <= 2:
                # own king can potentially block
                pass # not strong enough on its own, continue to next checks

        # King can't reach any stop square of the pawn
        if stm == chess.WHITE:
            stops = []
            if rank + 1 <= 7:
                stops.append(chess.square(file, rank+1))
            if rank == 1:  # double push possible?
                if board.piece_at(chess.square(file, rank+1)) is None and board.piece_at(chess.square(file, rank+2)) is None:
                    stops.append(chess.square(file, rank+2))
            if rank + 2 <= 7:
                stops.append(chess.square(file, rank+2))
        else:
            stops = []
            if rank - 1 >= 0:
                stops.append(chess.square(file, rank-1))
            if rank == 6:
                if board.piece_at(chess.square(file, rank-1)) is None and board.piece_at(chess.square(file, rank-2)) is None:
                    stops.append(chess.square(file, rank-2))
            if rank - 2 >= 0:
                stops.append(chess.square(file, rank-2))

        if stops and all(chess.square_distance(opp_king_sq, s) > 1 for s in stops):
            # King is too far to immediately block; check further
            # Recalculate properly: king needs to reach some square on the pawn's forward path
            # before the pawn promotes. If distance is strictly greater, it's unstoppable.
            if min_king_dist > dist_to_promo:
                return True

    return False
